import assert from 'node:assert/strict';
import { test } from 'node:test';
import { preprocessGuestCSS, rewriteGuestCSS } from '../src/guest/css.ts';

test('CSS input filtering preserves pairs and filters scalar-invalid code units and newlines', () => {
  assert.equal(
    preprocessGuestCSS('a\r\nb\rc\fd\0\ud800\udc00\ud800x\udc00'),
    'a\nb\nc\nd\ufffd\ud800\udc00\ufffdx\ufffd',
  );
  const input = 'a\r\n\0\ud800😀';
  assert.equal(preprocessGuestCSS(preprocessGuestCSS(input)), preprocessGuestCSS(input));
});

test('raw and CSS-escaped replacement characters produce identical URL inputs', () => {
  const seen = (text: string) => {
    const urls: string[] = [];
    rewriteGuestCSS(
      text,
      (url) => {
        urls.push(url);
        return 'data:,';
      },
      'value',
    );
    return urls;
  };
  for (const prefix of ['./', 'data:text/plain,', 'blob:https://fixture.invalid/']) {
    assert.deepEqual(seen(`url("${prefix}\ud800")`), [prefix + '\ufffd']);
    assert.deepEqual(seen(`u\\72l("${prefix}\\d800 ")`), [prefix + '\ufffd']);
    assert.deepEqual(seen(`url(${prefix}\0)`), [prefix + '\ufffd']);
    assert.deepEqual(seen(`url(${prefix}\\0 )`), [prefix + '\ufffd']);
  }
  assert.deepEqual(seen('url("./😀")'), ['./😀']);
  assert.deepEqual(seen('url("./\\d83d\\de00")'), ['./\ufffd\ufffd']);
  assert.deepEqual(seen('url("./%ED%A0%80")'), ['./%ED%A0%80']);
});
